import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"自托管总览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/self-hosted/index.md","filePath":"zh/self-hosted/index.md","lastUpdated":1788855895000}'),d={name:"zh/self-hosted/index.md"};function s(h,e,l,p,i,n){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="自托管总览" tabindex="-1">自托管总览 <a class="header-anchor" href="#自托管总览" aria-label="Permalink to &quot;自托管总览&quot;">​</a></h1><p>Memoh 以服务端形态运行，Web UI 和 Desktop 桌面版都是它的客户端。先选好服务端方案，再决定怎样访问它。</p><table tabindex="0"><thead><tr><th>场景</th><th>选择</th><th>原因</th></tr></thead><tbody><tr><td>什么都不想装，先试试</td><td><a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a></td><td>托管服务，功能一致，无需运维服务器。</td></tr><tr><td>共享服务器、远程访问、生产长期在线、对接 Telegram/Discord/飞书/微信/邮件等渠道、多用户或多租户</td><td><a href="/zh/self-hosted/docker.html">Server Deploy</a></td><td>Docker Compose 栈会持续运行后端、网页端、PostgreSQL（含 pgvector 记忆存储）和 workspace runtime。</td></tr><tr><td>想在自己电脑上用原生 App，或把这台电脑作为 Computer 共享给机器人</td><td><a href="/zh/self-hosted/desktop.html">Desktop 桌面版</a></td><td>连接 Cloud 或自托管服务端的原生客户端；不会在本地运行服务端。</td></tr></tbody></table><h2 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h2><p>Server Deploy 适合多人、远程、长期在线或多租户场景。机器人需要持续接入 Telegram、Discord、飞书、微信、公众号、邮件等外部渠道时，也应该用这一形态。</p><p>最快的路径见 <a href="/zh/guides/quick-start.html">快速开始</a>，完整参考见 <a href="/zh/self-hosted/docker.html">Server Deploy</a>。</p><h2 id="desktop-桌面版" tabindex="-1">Desktop 桌面版 <a class="header-anchor" href="#desktop-桌面版" aria-label="Permalink to &quot;Desktop 桌面版&quot;">​</a></h2><p>Desktop 适合想要托盘图标与快捷键的原生体验，或者想让服务端机器人使用你电脑上的文件、Shell 和浏览器的场景。Desktop 始终连接一个服务端（Cloud 或自托管），详见 <a href="/zh/self-hosted/desktop.html">Desktop</a>。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/zh/self-hosted/workspace-backends.html">Workspace backend</a> 解释 Docker、containerd、Apple 和本地 workspace 的差异。</li><li><a href="/zh/guides/computers.html">Computers</a> 介绍如何把自己的机器共享给机器人。</li></ul>',10)])])}const f=t(d,[["render",s]]);export{m as __pageData,f as default};
